import Foundation

enum HelpTopic: String, CaseIterable, Identifiable {
    case profiles, proxy, organization, library, storage, environment, keyboard, mcp
    var id: String { rawValue }

    var title: String {
        switch self {
        case .profiles: "Профили и запуск"
        case .proxy: "Прокси и проверка сети"
        case .organization: "Папки, теги и архив"
        case .library: "Шаблоны, фильтры и журнал"
        case .storage: "Импорт, снимки и восстановление"
        case .environment: "Среда и диагностика"
        case .keyboard: "Клавиатура и команды"
        case .mcp: "MCP: подключение к AI"
        }
    }

    var introduction: String {
        switch self {
        case .profiles: "Профиль — отдельная сессия браузера. Данные сайтов могут сохраняться постоянно или очищаться после сеанса. Создание не требует внешнего чекера."
        case .proxy: "Вставь одну строку или заполни поля. Протокол и порт должны совпадать с настройками поставщика."
        case .organization: "Организуй рабочие сессии без переноса данных браузера."
        case .library: "Повторяй настройки и быстро возвращайся к нужному набору профилей."
        case .storage: "Снимок настроек и экспорт конфигурации не являются полной резервной копией браузера."
        case .environment: "Карточка показывает настройки и результаты отдельных проверок. Настроенное значение не всегда измерено в браузере."
        case .keyboard: "Основные действия доступны из меню и с клавиатуры."
        case .mcp: "Локальный MCP управляет профилями, прокси, папками и запуском через выбранный AI-клиент. Новая настройка включает все действия с профилями. Только просмотр доступен в дополнительных настройках подключения."
        }
    }

    var sections: [(title: String, text: String)] {
        #if NEANTIK_CHROMIUM_ONLY
        return defaultSections.compactMap { section in
            switch (self, section.title) {
            case (.profiles, "Chromium или WebKit"):
                return ("Движок браузера", "Этот выпуск создаёт и запускает профили Chromium. Ранее созданные WebKit-профили и их данные сохраняются, но этот выпуск их не запускает и не дублирует.")
            case (.profiles, "Камера и микрофон в WebKit"),
                 (.profiles, "Загрузки в WebKit"), (.mcp, "WebKit через AI"):
                return nil
            case (.storage, "Очистить кэш"):
                return (section.title, "Останови профиль Chromium и выбери «Профиль → Очистить кэш…» либо действие в его меню. NeAntik сначала посчитает объём, затем повторно проверит и удалит только HTTP Cache и Code Cache. Cookies, IndexedDB, LocalStorage, Service Worker, вкладки и расширения не входят в очистку. При нестандартном пути или небезопасных файлах операция откажет; после незавершённой очистки нажми «Вернуть оставшийся кэш». Уже удалённые байты не восстанавливаются.")
            case (.mcp, "Прокси"):
                return (section.title, "profile_set_proxy принимает отдельные поля kind/host/port/username/password либо proxyLine с типом и порядком. При неоднозначности укажи order; proxy: null отключает прокси. Авторизованные HTTP, HTTPS и SOCKS5 используют отдельный локальный relay Chromium-профиля; сертификат HTTPS проверяется до передачи пароля. Пароль хранится в Связке ключей и не возвращается. profile_check_proxy — предварительная проверка доступности, она не подтверждает маршрут окна. Ранее созданные WebKit-профили в этом выпуске не запускаются.")
            case (.mcp, "FAQ и ошибки"):
                return (section.title, "Для настроек и запуска Chromium окно NeAntik можно закрыть: MCP работает отдельным процессом. «Management disabled»: выбери управление и скопируй настройку заново. «Revision conflict»: перечитай профиль и папки. «External session»: закрой браузер вручную. «Metadata unavailable»: открой приложение и проверь данные, не создавай пустой файл вручную. Чтобы отозвать права, верни режим чтения или отключи сервер и перезапусти клиент. После перемещения приложения скопируй новый абсолютный путь.")
            default:
                return section
            }
        }
        #else
        return defaultSections
        #endif
    }

    private var defaultSections: [(title: String, text: String)] {
        switch self {
        case .profiles: [
            ("Одноразовый сеанс", "Если включена очистка после закрытия, NeAntik удаляет данные сайтов после завершения сеанса. Настройки профиля, скачанные файлы и экспорт сохраняются. Если безопасно завершить очистку не удалось, повторный запуск блокируется до восстановления. Физическое стирание с SSD не гарантируется."),
            ("Chromium или WebKit", "При создании выбери движок. Старые профили остаются на Chromium. WebKit открывается в собственном окне NeAntik и использует отдельное постоянное хранилище сайтов. \(WebKitProxyFeature.launchEnabled ? "Без прокси используется системный WebKit, с прокси — изолированный runtime NeAntik; это не Safari.app. Предварительная проверка прокси не подтверждает маршрут окна." : "Используется системный WebKit, но не Safari.app. Прокси WebKit пока недоступен; вместо него прямое подключение не используется.") Параметры устройства, язык и часовой пояс предоставляет macOS. Движок существующего профиля нельзя менять — создай новый. Расширения и полная копия данных WebKit пока недоступны; для них используй Chromium. Для вкладок WebKit выбери «При запуске → Предыдущие вкладки». После штатного закрытия сохраняются их адреса и выбранная вкладка; полные адреса с параметрами остаются только в приватной папке на этом Mac и не попадают в MCP или экспорт настроек. История переходов, формы и продолжение загрузки не восстанавливаются. Специальные адреса и адреса с логином/паролем откроются пустыми. При переключении на стартовую страницу сохранённый список удаляется; если удалить его не удалось, NeAntik покажет предупреждение и не включит восстановление до очистки. WebKit поддерживает ⌘T (новая вкладка), ⌘W (закрыть текущую), ⌘⇧[ и ⌘⇧] (переключить вкладку), ⌘L (адрес), ⌘R (обновить), ⌘[ и ⌘] (назад/вперёд). Ссылка, открывающая новое окно, остаётся во вкладке этого профиля. Данные его вкладок общие, данные разных профилей разделены. Закрытие последней вкладки останавливает профиль. В одном окне — до 32 вкладок; при нехватке памяти новые не открываются. Автоматические всплывающие окна без действия пользователя заблокированы. При выходе из NeAntik его WebKit-окна тоже закрываются. Для долговременного хранения сайты должны успеть записать данные; сохранение последних изменений при аварийном завершении не гарантируется. MCP может создать WebKit-профиль и редактировать его настройки. Для запуска через AI оставь NeAntik открытым и включи доступ WebKit в справке MCP."),
            ("Камера и микрофон в WebKit", WebKitMediaFeature.isEnabled ? "Останови профиль и открой его настройки. В разделе «Камера и микрофон» выбери «Спрашивать у сайта» или «Запретить». Запрет относится ко всем вкладкам этого профиля и сохраняется в его копиях и экспорте настроек. «Спрашивать» передаёт решение WebKit и macOS: уже сохранённое решение сайта может использоваться повторно. NeAntik никогда не разрешает доступ автоматически. Системное разрешение NeAntik общее для приложения; его можно отозвать в «Системные настройки → Конфиденциальность и безопасность». Эта настройка не блокирует сетевой обмен WebRTC и не меняет отпечаток устройства. Профили с запретом требуют версии NeAntik, поддерживающей формат данных 3; старая версия откажет читать такой файл вместо игнорирования запрета." : "В этом выпуске доступ сайтов WebKit к камере и микрофону отключён. Настройки этой функции ещё проходят проверку и не показываются в редакторе или MCP. Cookies, вкладки, загрузки и остальные доступные функции WebKit продолжают работать. Обновление подготовлено для будущего выпуска с проверенными разрешениями; автоматически доступ к устройствам не выдаётся."),
            ("Загрузки в WebKit", "Нажми ссылку скачивания и выбери место в окне «Сохранить». Прогресс и кнопка отмены доступны через «Загрузки» рядом с адресом сайта. Готовый файл появляется только после завершения; существующие файлы не заменяются — выбери другое имя. Можно загружать до четырёх файлов одновременно, но выбирать место сохранения — по одному. «В Finder» показывает сохранённый файл и не открывает его. Закрытие всего профиля отменяет незавершённые загрузки. При выходе NeAntik ждёт подтверждения отмены; если WebKit не ответит, выход откладывается. Продолжение после перезапуска пока не поддерживается."),
            ("Создать и открыть", "Нажми «Новый профиль…» или ⌘N. Укажи имя, при необходимости прокси, затем создай профиль. Выбери его и нажми «Запустить». Каждая запись хранит свои cookies и данные сайтов."),
            ("Изменить и остановить", "Останови профиль перед редактированием настроек сети или удалением. Повторное нажатие не создаёт второй браузер того же профиля. Если браузер открыт другим manager, закрой его вручную — NeAntik не завершает чужой процесс."),
            ("После перезапуска", "Профили сохраняются на диске. Если manager перезапущен при работающем браузере, он проверяет процессы перед новым запуском. Предупреждение о занятом профиле помогает не открыть один каталог дважды. В настройках профиля выбери, что открывать: стартовую страницу или предыдущие вкладки. Во втором режиме стартовый адрес используется только при первом запуске. Штатно закрой браузер, чтобы он сохранил вкладки; после сбоя сохранится только то, что успел записать Chromium. Для пустой стартовой страницы укажи about:blank. Срок авторизации определяет сайт, cookies сессии могут истечь после закрытия.\nУ остановленного профиля нажми «Расширения профиля…». NeAntik покажет сохранённые названия, версии и запрошенные разрешения. Неизвестный статус обозначается прямо; список не подтверждает безопасность расширений. Кнопка «Проверить файл CRX…» проверяет подпись разработчика CRX3, целостность всех записей архива и показывает запрошенные разрешения. Проверка не устанавливает и не запускает расширение, не подтверждает безопасность автора или совместимость с Chromium. Выбери способ подготовки. «Подготовить исходный CRX» сохраняет точный подписанный файл без изменения manifest. Перед показом в Finder файл проверяется повторно. В нужном профиле открой chrome://extensions/, включи режим разработчика и перетащи CRX на страницу; проверь запрос разрешений. Chromium может отказать в установке несовместимого пакета. Альтернатива для Manifest V3 — «Подготовить распакованную папку»: проверенные файлы сохраняются внутри BrowserData этого профиля. Если в manifest нет публичного ключа, NeAntik добавит ключ проверенной подписи для сохранения ID. Исходный CRX и описание подготовки сохраняются отдельно от распакованных файлов. Затем открой chrome://extensions/, включи режим разработчика и выбери «Загрузить распакованное расширение». В выборе папки нажми ⌘⇧G и вставь путь, скопированный в NeAntik. Не перемещай и не удаляй эту папку: она нужна для повторных запусков. Фактическую установку и разрешения определяет Chromium. Нажми «Открыть браузер», затем меню ⋮ → Расширения → Управление расширениями. Или скопируй chrome://extensions/ из центра и вставь в адресную строку. Там можно установить, включить, отключить и удалить расширение. После закрытия браузера обнови список в NeAntik. Стартовая страница и настройки сети сохраняются. Папки пакетов могут оставаться после удаления и не означают, что расширение установлено.")]
        case .proxy: [
            ("Форматы одной строки", "login:password@host:port\nhost:port:login:password\nhost:port\nhttp://host:port\nsocks5://host:port\nДля HTTP с авторизацией используй первый формат; префикс http:// можно добавить перед строкой. Для неоднозначного порядка выбери формат явно. Для массового создания используй «Создать профили из списка прокси…»: одна строка — один профиль, ошибки видны до сохранения."),
            ("HTTP, HTTPS и SOCKS5", "HTTP-прокси может открывать HTTPS-сайты через CONNECT. Тип HTTPS означает TLS-соединение именно с прокси-сервером: обычный HTTP-порт с этим типом даст ошибку. HTTP, HTTPS и SOCKS5 с авторизацией подключаются через отдельный локальный relay профиля: он передаёт сохранённые данные прокси без окна входа в браузере. Для HTTPS сначала проверяется сертификат сервера средствами macOS. Не угадывай протокол по номеру порта."),
            ("Определить тип", "Если известны только адрес и порт, в редакторе нажми «Определить тип без пароля». NeAntik сделает короткие пробы SOCKS5 и HTTP без логина и пароля. Затем нажми «Использовать HTTP» или «Использовать SOCKS5». Вставка строки сама по себе не отправляет запросов. Если тип не определён, уточни его у провайдера: HTTPS и неоднозначные ответы выбираются вручную. Это определение протокола, а не проверка авторизации или доступа к сайтам; профиль автоматически не сохраняется."),
            ("Что проверяется", "«Проверить прокси» — отдельная диагностика доступности. Перед запуском прокси-профиля NeAntik повторяет подготовку сети и геоконтекста. 429 означает ограничение сервиса определения IP, а не доказанную поломку прокси. Резервные сервисы помогают различить эти причины; если согласованный контекст получить нельзя, запуск остановится с объяснением."),
            ("Свой адрес диагностики", "В редакторе и карточке остановленного профиля нажми «Свой адрес диагностики…». Укажи HTTPS-адрес без логина, пароля, query и fragment. Ответ сервиса: JSON с полем ip (IPv4 или IPv6). Сохранение адреса не запускает сеть; запрос отправляется только после отдельного согласия. Переадресации и fallback к публичным сервисам отключены. Результат показывает доступность через curl и заявленный IP на момент проверки, не меняет геоконтекст и не измеряет маршрут Chromium. Проверка подготовки запуска остаётся отдельной."),
            ("Авторизация и ошибки", "Пароль хранится в Связке ключей; логин — в локальных настройках профиля. Для HTTP, HTTPS и SOCKS5 сохранённые данные передаются автоматически через relay. При ошибке сертификата HTTPS-прокси авторизация не отправляется. Проверь протокол, порт и учётные данные при ошибке. Скрытого перехода на прямое подключение нет; успешная проверка manager сама по себе не доказывает маршрут Chromium.")]
        case .organization: [
            ("Поиск и папки", "Поиск находит названия, заметки, теги и папки. Выбери область слева, чтобы сузить список. Папки группируют записи; перемещение в папку не переносит каталог BrowserData."),
            ("Теги и закрепление", "Теги меняются через «Изменить…» → «Организация и оформление». Один профиль может иметь несколько тегов. В меню «Действия» можно закрепить часто используемый профиль. Закреплённые доступны в отдельной области."),
            ("Архив или удаление", "Архив скрывает профиль из обычного списка, сохраняя его данные. Вернуть его можно из области «Архив». Перед удалением останови профиль. Для Chromium его каталог перемещается в Корзину; возврат файлов не восстанавливает профиль полностью. Для WebKit macOS удаляет отдельное хранилище сайтов без возможности вернуть его из Корзины. Запись профиля и сохранённые вкладки также удаляются. Неожиданные локальные файлы NeAntik сохраняет отдельно и показывает предупреждение. Если операция прервалась, профиль скрыт и заблокирован: в верхней части окна нажми «Завершить удаление…». Не удаляй служебные файлы вручную. Пароль очищается после сохранения удаления; при ошибке NeAntik сообщит о незавершённой очистке. Снимок настроек не возвращает cookies и авторизацию. Для обратимого скрытия используй архив.")]
        case .library: [
            ("Шаблоны", "Шаблон сохраняет имя, стартовую страницу, теги и папку выбранного профиля. Cookies, пароли, прокси и прежняя identity не копируются. Перед созданием проверь настройки; прокси задаётся отдельно."),
            ("Сохранённые фильтры", "Фильтр сохраняет текущую область, папку, тег и поисковый запрос. «Применить» меняет представление списка, а не сами профили."),
            ("Журнал", "Последние 200 локальных операций помогают понять, что произошло. Журнал исключает имена профилей, адреса, IP и содержимое данных. Его очистка не удаляет профили.")]
        case .storage: [
            ("Импорт закладок", "Меню «Профили» → «Создать профиль из закладок…». Выбери экспорт Netscape HTML или файл Bookmarks Chromium версии 1, проверь количество и задай название. Создаётся новый профиль с новой identity без автоматического запуска. Переносятся HTTP/HTTPS-закладки и папки; cookies, пароли, расширения и настройки исходного браузера не переносятся. Лимиты: 8 МБ, 10 000 элементов и 32 уровня папок. Неподдерживаемый формат или URL останавливает весь импорт."),
            ("Очистить кэш", "Останови профиль и выбери «Профиль → Очистить кэш…» либо действие в его меню. Для WebKit очищаются только HTTP-кэши в памяти и на диске, без точного подсчёта объёма; дождись завершения операции. Остальное ниже относится к Chromium: NeAntik сначала посчитает объём, затем повторно проверит и удалит только HTTP Cache и Code Cache. Cookies, IndexedDB, LocalStorage, Service Worker, вкладки и расширения не входят в очистку. При нестандартном cache path или небезопасных файлах операция откажет; после незавершённой очистки нажми «Вернуть оставшийся кэш». Возвращаются только папки, подтверждённые журналом и inode; уже удалённые байты не восстанавливаются. При повреждённом журнале сохрани папку и обратись в поддержку."),
            ("Экспорт конфигурации", "Экспорт создаёт файл настроек для обмена. В него не входят BrowserData, cookies, заметки, identity и пароли из Связки ключей. Зашифрованный экспорт защищается заданным паролем; без него файл не открыть."),
